        assert(perm.id() == pre.backing_cells.index(head as int)) by {
            assert(pre.valid_storage_at_idx(head));
        };
        assert(perm.is_init()) by {
            assert(pre.in_active_range(head));
            assert(pre.valid_storage_at_idx(head));
        };
    }
